<?php
// Generic error page. Preserve the actual HTTP status when possible.
$status = http_response_code();
if (!$status || $status < 400) $status = 500;
?>
<!DOCTYPE html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Something Broke — <?php echo htmlspecialchars((string)$status); ?></title>
